{
  "root_causes": [
    {
      "service": "ts-admin-user-service",
      "fault_kind": "application_method_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p, count(*) n, approx_quantile(duration,0.5)/1e6 p50_ms, approx_quantile(duration,0.95)/1e6 p95_ms FROM (SELECT 'abn' p, duration FROM abnormal_traces WHERE service_name='ts-admin-user-service' AND span_name='AdminUserController.getAllUsers' UNION ALL SELECT 'norm', duration FROM normal_traces WHERE service_name='ts-admin-user-service' AND span_name='AdminUserController.getAllUsers') GROUP BY p",
          "claim": "AdminUserController.getAllUsers p50 rose from about 6.8 ms normal to about 1,650 ms abnormal, a uniform added delay."
        },
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, c.span_name caller_span, s.service_name callee, s.span_name callee_span, count(*) n, approx_quantile(c.duration,0.5)/1e6 caller_p50_ms, approx_quantile(s.duration,0.5)/1e6 callee_p50_ms FROM abnormal_traces c JOIN abnormal_traces s ON c.trace_id=s.trace_id AND c.span_id=s.parent_span_id WHERE c.service_name='ts-ui-dashboard' AND s.service_name='ts-admin-user-service' GROUP BY ALL ORDER BY n DESC",
          "claim": "ts-ui-dashboard GET /api/v1/adminuserservice/users takes about 1,655 ms p50, matching the callee's time."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, approx_quantile(duration,0.5)/1e6 p50_ms FROM abnormal_traces WHERE service_name='ts-admin-user-service' AND span_name IN ('GET','AdminUserController.getAllUsers') GROUP BY ALL",
